## 4. Core Components (React Example)

### 4.1 `ProductCard.jsx`

```tsx
import { Card, CardContent, CardFooter } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { useCart } from '@/store/cartSlice';

export default function ProductCard({ product }) {
  const { addToCart } = useCart();

  return (
    <Card className="flex flex-col h-full">
      <CardContent className="flex-1">
        <img
          src={product.image}
          alt={product.title}
          className="w-full h-48 object-cover rounded-md"
        />
        <h3 className="mt-4 font-semibold">{product.title}</h3>
        <p className="text-sm text-muted-foreground">{product.category}</p>
        <p className="mt-2 font-bold">{formatPrice(product.price)}</p>
      </CardContent>
      <CardFooter>
        <Button onClick={() => addToCart(product)} className="w-full">
          Add to cart
        </Button>
      </CardFooter>
    </Card>
  );
}
```

### 4.2 `CartIcon.jsx`

```tsx
import { useSelector } from 'react-redux';
import { Badge } from '@/components/ui/badge';
import { ShoppingCartIcon } from '@heroicons/react/outline';

export default function CartIcon() {
  const itemCount = useSelector((state) => state.cart.totalQuantity);

  return (
    <div className="relative">
      <ShoppingCartIcon className="h-6 w-6" />
      {itemCount > 0 && (
        <Badge variant="secondary" className="absolute -top-1 -right-1">
          {itemCount}
        </Badge>
      )}
    </div>
  );
}
```

### 4.3 `Header.jsx`

```tsx
import { Link } from 'react-router-dom';
import CartIcon from './CartIcon';

export default function Header() {
  return (
    <header className="bg-background border-b">
      <nav className="container mx-auto flex items-center justify-between py-4">
        <Link to="/" className="text-xl font-bold">
          ShopLogo
        </Link>
        <div className="flex items-center space-x-4">
          <Link to="/cart" className="relative">
            <CartIcon />
          </Link>
          <Link to="/login" className="text-sm">
            Sign In
          </Link>
        </div>
      </nav>
    </header>
  );
}
```

