## 5. API Integration

### 5.1 `services/api.js`

```js
import axios from 'axios';

const api = axios.create({
  baseURL: import.meta.env.VITE_API_URL,
  headers: {
    'Content-Type': 'application/json',
  },
});

export const fetchProducts = () => api.get('/products');
export const fetchProductById = (id) => api.get(`/products/${id}`);
export const addToCartApi = (product) => api.post('/cart', product);
// ... other endpoints
```

### 5.2 Using React Query

```tsx
import { useQuery } from '@tanstack/react-query';
import { fetchProducts } from '@/services/api';

export default function Home() {
  const { data, isLoading, error } = useQuery(['products'], fetchProducts);

  if (isLoading) return <Spinner />;
  if (error) return <p>Error loading products.</p>;

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
      {data.map((p) => (
        <ProductCard key={p.id} product={p} />
      ))}
    </div>
  );
}
```

---

## 6. State Management (Redux Toolkit)

```js
// store/cartSlice.js
import { createSlice } from '@reduxjs/toolkit';

const cartSlice = createSlice({
  name: 'cart',
  initialState: { items: [], totalQuantity: 0 },
  reducers: {
    addToCart(state, action) {
      const product = action.payload;
      const existing = state.items.find((i) => i.id === product.id);
      if (existing) {
        existing.quantity += 1;
      } else {
        state.items.push({ ...product, quantity: 1 });
      }
      state.totalQuantity += 1;
    },
    // removeFromCart, clearCart, etc.
  },
});

export const { addToCart } = cartSlice.actions;
export default cartSlice.reducer;
```

---

## 7. Testing

### 7.1 Unit Test for `ProductCard`

```tsx
import { render, screen, fireEvent } from '@testing-library/react';
import ProductCard from '@/components/ProductCard';
import { Provider } from 'react-redux';
import store from '@/store';

test('renders product details and handles add to cart', () => {
  const product = {
    id: 1,
    title: 'Test Shirt',
    category: 'Clothing',
    price: 29.99,
    image: '/test.jpg',
  };

  render(
    <Provider store={store}>
      <ProductCard product={product} />
    </Provider>
  );

  expect(screen.getByText('Test Shirt')).toBeInTheDocument();
  expect(screen.getByText('$29.99')).toBeInTheDocument();

  fireEvent.click(screen.getByRole('button', { name: /add to cart/i }));
  expect(store.getState().cart.totalQuantity).toBe(1);
});
```

### 7.2 Integration Test for Home Page

```tsx
import { render, screen } from '@testing-library/react';
import Home from '@/pages/Home';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { rest } from 'msw';
import { setupServer } from 'msw/node';

const server = setupServer(
  rest.get('/products', (req, res, ctx) => {
    return res(
      ctx.json([
        { id: 1, title: 'Item 1', price: 10, image: '/1.jpg', category: 'Cat' },
      ])
    );
  })
);

beforeAll(() => server.listen());
afterEach(() => server.resetHandlers());
afterAll(() => server.close());

test('displays products after fetch', async () => {
  const queryClient = new QueryClient();
  render(
    <QueryClientProvider client={queryClient}>
      <Home />
    </QueryClientProvider>
  );

  expect(await screen.findByText('Item 1')).toBeInTheDocument();
});
```

---

## 8. Accessibility & SEO

| Feature | Implementation |
|---------|----------------|
| **Meta tags** | Use `react-helmet` or Next.js `<Head>` |
| **Structured data** | Add JSON‑LD for products, breadcrumbs, reviews |
| **Keyboard navigation** | Ensure all interactive elements are focusable |
| **ARIA labels** | Add `aria-label` to icons, buttons |
| **Color contrast** | Verify with Lighthouse or axe |

**Example JSON‑LD for a product**

```html
<script type="application/ld+json">
{
  "@context": "https://schema.org",
  "@type": "Product",
  "name": "Test Shirt",
  "image": "/test.jpg",
  "description": "A stylish shirt.",
  "sku": "TS-001",
  "offers": {
    "@type": "Offer",
    "priceCurrency": "USD",
    "price": "29.99",
    "availability": "https://schema.org/InStock"
  }
}
</script>
```

---

## 9. Deployment Pipeline (GitHub Actions)

```yaml
name: CI/CD

on:
  push:
    branches: [main]
  pull_request:

jobs:
  build:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-node@v4
        with:
          node-version: '20'
      - run: npm ci
      - run: npm run lint
      - run: npm run test -- --coverage
      - run: npm run build
      - uses: actions/upload-artifact@v4
        with:
          name: build
          path: dist

  deploy:
    needs: build
    runs-on: ubuntu-latest
    environment: production
    steps:
      - uses: actions/download-artifact@v4
        with:
          name: build
      - uses: peaceiris/actions-gh-pages@v3
        with:
          github_token: ${{ secrets.GITHUB_TOKEN }}
          publish_dir: ./dist
```

> **Tip:** If you’re using Vercel or Netlify, you can simply connect the repo and let them handle the build & deploy.

---

## 10. Checklist Before Launch

- [ ] All core pages (catalog, product, cart, checkout) are responsive.
- [ ] API calls are cached; no unnecessary re‑fetches.
- [ ] Accessibility audit passes (WCAG AA).
- [ ] Lighthouse score ≥ 90 (performance, accessibility, best practices, SEO).
- [ ] Unit & integration tests cover ≥ 80 % of critical paths.
- [ ] CI pipeline runs on every PR.
- [ ] Environment variables are stored securely (e.g., `.env.production`).
- [ ] SEO meta tags & structured data are present.
- [ ] Analytics (Google Analytics, Plausible) is integrated.
- [ ] Error boundaries catch runtime errors.
- [ ] Dark mode toggle works (optional).

